package com.alpharip.staffmod.BuildTimelapse.core;
import com.alpharip.staffmod.BuildTimelapse.camera.CameraController;import com.alpharip.staffmod.BuildTimelapse.capture.CaptureService;import com.alpharip.staffmod.BuildTimelapse.timeline.Timeline;import java.io.IOException;
/** Coordinates project, camera and interval capture. tick() must be called once per client tick. */
public final class BuildTimelapseController {
 private final BuildTimelapseProject p;private final CameraController camera;private final CaptureService capture;private final Timeline timeline;private final ProjectStore store;private boolean active,closed;private volatile String lastFailure;
 public BuildTimelapseController(BuildTimelapseProject p,CameraController c,CaptureService s,Timeline t,ProjectStore st){if(p==null||c==null||s==null||t==null||st==null)throw new IllegalArgumentException();this.p=p;camera=c;capture=s;timeline=t;store=st;}
 public synchronized void start(){if(closed)throw new IllegalStateException("Build Timelapse controller is shut down");if(active)return;lastFailure=null;try{camera.activate();capture.start();p.start(System.currentTimeMillis());active=true;}catch(Exception failure){try{capture.stop();}finally{try{camera.deactivate();}catch(Exception cleanup){failure.addSuppressed(cleanup);}}lastFailure=failure.toString();throw new IllegalStateException("Could not start Build Timelapse; camera activation or capture setup failed",failure);}}
 public synchronized void pause(){if(active){long now=System.currentTimeMillis();capture.pause();camera.pausePath(now);p.pause(now);active=false;}}
 public synchronized void resume(){if(closed)throw new IllegalStateException("Build Timelapse controller is shut down");if(!active){if(!camera.isActive()||!capture.isRunning()||!capture.isPaused())throw new IllegalStateException("Recording session is not paused; restart the session");long now=System.currentTimeMillis();p.resume(now);camera.resumePath(now);capture.resume();active=true;}}
 public synchronized void tick(long now){if(closed||!camera.isActive())return;try{camera.tick(now);if(active)capture.tick(now);}catch(Exception failure){lastFailure=failure.toString();try{stop();}catch(RuntimeException cleanup){lastFailure=lastFailure+"; cleanup: "+cleanup;}}}
 public synchronized void stop(){capture.stop();if(p.getStarted()>0)p.stop(System.currentTimeMillis());camera.stopPath();try{camera.deactivate();}catch(Exception e){lastFailure="Camera cleanup failed: "+e;}finally{active=false;}}
 public synchronized void save()throws IOException{store.save(p,timeline);}public synchronized boolean isActive(){return active;}public synchronized String getLastFailure(){return lastFailure;}
 public CameraController getCamera(){return camera;}public Timeline getTimeline(){return timeline;}public CaptureService getCapture(){return capture;}public BuildTimelapseProject getProject(){return p;}
 public synchronized void shutdown(){if(closed)return;try{stop();}finally{closed=true;capture.shutdown();}}
}